INSERT INTO public.audit_log (id, actor_id, actor_name, action_type, target_type, target_id, meta, created_at) VALUES ('61a71de2-9e76-4b1b-8340-d027d79a9c99', 'd4cfb01c-8061-40e0-b7fe-6d5406debc72', 'Mahmoud Gamal', 'product.updated', 'product', '7e1bec49-f587-4e64-b9d5-44adf4900366', '{"slug": "linkedin-premium", "changes": {"description_ar": {"to": " ما تضيعش وقت… ابدأ النهارده وطوّر شغلك في التصميم!\n\n🔥 الدفع بعد التفعيل -وضمان طوال مدة الاشتراك 🔥\n\nدلوقتي تقدر تحصل على اشتراك Canva Pro على حسابك الشخصي بسعر يبدأ من 50ج بس!\n\n💎 مميزات Canva Pro:\n\n🎨 أكتر من 420,000 قالب جاهز\n📸 ملايين الصور والفيديوهات الجاهزة للاستخدام\n☁️ 100 جيجا تخزين\n📚 عناصر عربية وأجنبية تناسب كل التصميمات\n\n⚡ أدوات AI هتفرق جدًا في شغلك:\n\n✨ رفع جودة الصور لحد 16x\n✨ إزالة الخلفيات بدقة عالية\n✨ سحب وتحريك أي عنصر بسهولة باستخدام Magic Grab\n✨ توسيع الكادر بدون تشويه باستخدام Magic Expand\n✨ تغيير مقاسات التصميم لكل منصات السوشيال بنقرة واحدة\n\n✅ ليه تشترك معانا؟\n\n✔️ حساب رسمي على حسابك الشخصي\n✔️ ضمان طوال مدة الاشتراك\n✔️ تفعيل مباشر\n✔️ الدفع بعد التفعيل\n✔️ شغال على كل الأجهزة\n✔️ تقدر تستخدمه على أكتر من جهاز\n\n💬 متضيعش الفرصة… تواصل معانا دلوقتي وابدأ رحلتك للاحتراف!\n\n#CanvaPro #Canva #تصميم #اشتراكات_رقمية #ذكاء_اصطناعي #AI #تصميم_جرافيك #سوشيال_ميديا عرض أقل\n", "from": "بص بقى يا معلم \nعندنا باقات كل حاجة تتخيلها\nتيست\nتيست"}}, "name_ar": "LinkedIn Premium"}', '2026-07-22 21:19:44.936583+00') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_log (id, actor_id, actor_name, action_type, target_type, target_id, meta, created_at) VALUES ('fbbb60ab-1454-4b9f-bae0-efa6e0900d57', 'd4cfb01c-8061-40e0-b7fe-6d5406debc72', 'Mahmoud Gamal', 'product.updated', 'product', '7e1bec49-f587-4e64-b9d5-44adf4900366', '{"slug": "linkedin-premium", "changes": {"description_ar": {"to": " ما تضيعش وقت… ابدأ النهارده وطوّر شغلك في التصميم!\nاي حاجة كدا تيست\n\nمثال اي حاجة", "from": " ما تضيعش وقت… ابدأ النهارده وطوّر شغلك في التصميم!\n\n🔥 الدفع بعد التفعيل -وضمان طوال مدة الاشتراك 🔥\n\nدلوقتي تقدر تحصل على اشتراك Canva Pro على حسابك الشخصي بسعر يبدأ من 50ج بس!\n\n💎 مميزات Canva Pro:\n\n🎨 أكتر من 420,000 قالب جاهز\n📸 ملايين الصور والفيديوهات الجاهزة للاستخدام\n☁️ 100 جيجا تخزين\n📚 عناصر عربية وأجنبية تناسب كل التصميمات\n\n⚡ أدوات AI هتفرق جدًا في شغلك:\n\n✨ رفع جودة الصور لحد 16x\n✨ إزالة الخلفيات بدقة عالية\n✨ سحب وتحريك أي عنصر بسهولة باستخدام Magic Grab\n✨ توسيع الكادر بدون تشويه باستخدام Magic Expand\n✨ تغيير مقاسات التصميم لكل منصات السوشيال بنقرة واحدة\n\n✅ ليه تشترك معانا؟\n\n✔️ حساب رسمي على حسابك الشخصي\n✔️ ضمان طوال مدة الاشتراك\n✔️ تفعيل مباشر\n✔️ الدفع بعد التفعيل\n✔️ شغال على كل الأجهزة\n✔️ تقدر تستخدمه على أكتر من جهاز\n\n💬 متضيعش الفرصة… تواصل معانا دلوقتي وابدأ رحلتك للاحتراف!\n\n#CanvaPro #Canva #تصميم #اشتراكات_رقمية #ذكاء_اصطناعي #AI #تصميم_جرافيك #سوشيال_ميديا عرض أقل\n"}}, "name_ar": "LinkedIn Premium"}', '2026-07-22 21:24:34.071742+00') ON CONFLICT DO NOTHING;
