INSERT INTO public.audit_log (id, actor_id, actor_name, action_type, target_type, target_id, meta, created_at) VALUES ('3ba05b49-3f5c-44de-b4ff-9da9296f553f', 'd4cfb01c-8061-40e0-b7fe-6d5406debc72', 'Mahmoud Gamal', 'product.updated', 'product', 'eb49480d-3788-4986-a9cb-7ccf7df2969b', '{"slug": "capcut-pro", "changes": {"description_ar": {"to": "أفكارك واقفة؟ خلّي الذكاء ينجز معاك خطوة بخطوة 🌊❄️\nشـــا ت جــــي بــــي تــــي بلــــس\n\nمش مجرد شات… ده مساعدك اليومي في الشغل، الدراسة، المحتوى، البرمجة وتنظيم الأفكار.\n\nمع الاشتراك تقدر تستفيد من:\n✅ إجابات أذكى وأسرع\n✅ كتابة محتوى، تلخيص وترجمة باحتراف\n✅ رفع ملفات وتحليلها بدل ما تضيع وقتك\n✅ توليد صور وأفكار للتصميم والمحتوى\n✅ بحث أعمق ومساعدة في الوصول لمعلومات أحدث\n✅ صوت، صور، ملفات، وذاكرة تساعدك تكمّل شغلك بسهولة\n✅ مناسب للشغل، الدراسة، التسويق، البرمجة وصناعة المحتوى\n\n🔥 خصم أكتر من 50% لفترة محدودة\n\nابدأ تجربتك الآن…\nوابعتلنا دلوقتي 💙\n", "from": "النسخة الاحترافية من CapCut للمونتاج"}}, "name_ar": "CapCut PRO"}', '2026-07-22 22:05:09.007613+00') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_log (id, actor_id, actor_name, action_type, target_type, target_id, meta, created_at) VALUES ('aba307d8-3fe9-45b4-bca3-23b77bde37d8', 'd4cfb01c-8061-40e0-b7fe-6d5406debc72', 'Mahmoud Gamal', 'product.updated', 'product', 'eb49480d-3788-4986-a9cb-7ccf7df2969b', '{"slug": "capcut-pro", "changes": {"description_ar": {"to": "**أفكارك واقفة؟ خلّي الذكاء ينجز معاك خطوة بخطوة 🌊❄️\nشـــا ت جــــي بــــي تــــي بلــــس\n\nمش مجرد شات… ده مساعدك اليومي في الشغل، الدراسة، المحتوى، البرمجة وتنظيم الأفكار.\n\nمع الاشتراك تقدر تستفيد من:\n✅ إجابات أذكى وأسرع\n✅ كتابة محتوى، تلخيص وترجمة باحتراف\n✅ رفع ملفات وتحليلها بدل ما تضيع وقتك\n✅ توليد صور وأفكار للتصميم والمحتوى\n✅ بحث أعمق ومساعدة في الوصول لمعلومات أحدث\n✅ صوت، صور، ملفات، وذاكرة تساعدك تكمّل شغلك بسهولة\n✅ مناسب للشغل، الدراسة، التسويق، البرمجة وصناعة المحتوى\n\n🔥 خصم أكتر من 50% لفترة محدودة\n\nابدأ تجربتك الآن…\nوابعتلنا دلوقتي 💙\n**", "from": "أفكارك واقفة؟ خلّي الذكاء ينجز معاك خطوة بخطوة 🌊❄️\nشـــا ت جــــي بــــي تــــي بلــــس\n\nمش مجرد شات… ده مساعدك اليومي في الشغل، الدراسة، المحتوى، البرمجة وتنظيم الأفكار.\n\nمع الاشتراك تقدر تستفيد من:\n✅ إجابات أذكى وأسرع\n✅ كتابة محتوى، تلخيص وترجمة باحتراف\n✅ رفع ملفات وتحليلها بدل ما تضيع وقتك\n✅ توليد صور وأفكار للتصميم والمحتوى\n✅ بحث أعمق ومساعدة في الوصول لمعلومات أحدث\n✅ صوت، صور، ملفات، وذاكرة تساعدك تكمّل شغلك بسهولة\n✅ مناسب للشغل، الدراسة، التسويق، البرمجة وصناعة المحتوى\n\n🔥 خصم أكتر من 50% لفترة محدودة\n\nابدأ تجربتك الآن…\nوابعتلنا دلوقتي 💙\n"}}, "name_ar": "CapCut PRO"}', '2026-07-22 22:05:37.289015+00') ON CONFLICT DO NOTHING;
